"""Snapping clock times to a fixed step for payroll."""

from typing import Iterable, List

from hourglass.parsing import format_clock
from hourglass.models import Span


def check_step(step: int) -> None:
    """The step must be positive and divide evenly into an hour."""
    if step <= 0 or 60 % step:
        raise ValueError(f"step must divide an hour evenly: {step}")


def snap_minute(value: int, step: int) -> int:
    """Nearest multiple of step, with exact halves going up."""
    return (2 * value + step) // (2 * step) * step


def round_span(span: Span, step: int) -> Span:
    check_step(step)
    return Span(snap_minute(span.start, step), snap_minute(span.end, step))


def format_duration(minutes: int) -> str:
    hours, remainder = divmod(minutes, 60)
    return f"{hours}h {remainder:02d}m"


def label_span(span: Span) -> str:
    clocks = f"{format_clock(span.start)}-{format_clock(span.end)}"
    return f"{clocks} ({format_duration(span.minutes)})"


def rounded_labels(spans: Iterable[Span], step: int) -> List[str]:
    """Round each span to the step and label it, such as 09:00-17:15 (8h 15m)."""
    check_step(step)
    return [label_span(round_span(span, step)) for span in spans]

