# owner: platform
import unittest

from hourglass.rounding import rounded_labels
from hourglass.parsing import parse_span


class RoundedLabelTests(unittest.TestCase):
    def test_snaps_to_nearest_step(self):
        spans = [parse_span("09:07-17:08")]
        self.assertEqual(rounded_labels(spans, 15), ["09:00-17:15 (8h 15m)"])

    def test_exact_half_rounds_up(self):
        spans = [parse_span("09:02-10:28")]
        self.assertEqual(rounded_labels(spans, 5), ["09:00-10:30 (1h 30m)"])
        spans = [parse_span("09:30-10:45")]
        self.assertEqual(rounded_labels(spans, 60), ["10:00-11:00 (1h 00m)"])

    def test_one_label_per_span(self):
        spans = [parse_span("08:00-09:00"), parse_span("13:00-13:40")]
        self.assertEqual(
            rounded_labels(spans, 30),
            ["08:00-09:00 (1h 00m)", "13:00-13:30 (0h 30m)"]
        )

    def test_bad_steps_raise(self):
        spans = [parse_span("08:00-09:00")]
        for step in (0, -15, 7, 90):
            with self.assertRaises(ValueError):
                rounded_labels(spans, step)


if __name__ == "__main__":
    unittest.main()
